function queued(id, priority, label, entry, owner, evidence = []) {
  return {
    id, priority, status: 'queued', label, entry, sourceOwner: owner,
    forks: 'Branch inventory pending.',
    handoff: 'Exact draft, settings, selection, and context handoff audit pending.',
    review: 'Review and approval boundary audit pending.',
    output: 'Output artifact, content, and owner verification pending.',
    returnRoute: 'Completion Open/Return route audit pending.',
    cancelRetry: 'Cancellation/failure retained-state and retry audit pending.',
    expectedResult: 'Must prove actual output matches the displayed destination and approval intent.',
    repetition: 'Chooser, setup, and confirmation repetition audit pending.',
    guidance: 'Must state a concise next action, current draft/staged/saved state, exact destination or “choose at next step,” overwrite/new-output policy, and remaining review/build/apply work.',
    destinationDisplay: 'Not yet audited; the UI must never imply Saved while the destination is unknown.',
    evidence,
    unresolved: 'Complete end-to-end behavioral/output fixture and compact guidance audit pending.'
  };
}

